text:
Functions
Syntax:
function_name() {
    commands
}
Examples:
# Simple function
greet() {
    echo "Hello, $1"
}

greet "Bontu"

# With return value
add() {
    echo $(( $1 + $2 ))
}

result=$(add 5 3)
Local variables:
demo() {
    local local_var="I am local"
    global_var="Modified"
}
Exit codes:
check_file() {
    if [[ -f "$1" ]]; then
        return 0
    else
        return 1
    fi
}

check_file "/etc/passwd"
echo "Exit code: $?"
